func searchRange(nums []int, target int) []int {
    left := lowerBound(nums, target)
    right := upperBound(nums, target)
    if left > right {
        return []int{-1, -1}
    }
    return []int{left, right}
}

func lowerBound(nums []int, target int) int {
    lo, hi := 0, len(nums)-1
    for lo <= hi {
        mid := lo + (hi-lo)/2
        if nums[mid] < target {
            lo = mid + 1
        } else {
            hi = mid - 1
        }
    }
    return lo
}

func upperBound(nums []int, target int) int {
    lo, hi := 0, len(nums)-1
    for lo <= hi {
        mid := lo + (hi-lo)/2
        if nums[mid] <= target {
            lo = mid + 1
        } else {
            hi = mid - 1
        }
    }
    return hi
}
